// Types of the sim WASM module (sim/wasm). Load wasm_exec.js (from GOROOT/lib/wasm), instantiate sim.wasm,
// `go.run(instance)`; when the module is ready it sets globalThis.fireline_sim and calls
// globalThis.fireline_sim_ready() if that is a function.
//
// All functions take/return STRINGS (JSON). uint64 values (seed, StateHash) are strings: JS numbers lose
// precision above 2^53. Snapshot/Result keep the Go field names (same JSON as sim/testdata/replays/G*.json).
// Contract: modules/sim/CONTRACT.md (0.2.x; state() since 0.2.5; 0.2.6 adds only Rules.Buildings[].DmgGrowthPermille, Rules is untyped here). Generated by hand from sim/types.go + sim/rules.go; keep in sync.

export type Cell = { X: number; Y: number };

export type OpName = "deploy" | "load" | "start" | "move" | "attack" | "ability" | "cast" | "end_turn" | "retreat";

/** One player command. `turn` is 0 for deployment, then 1..N and never decreases. */
export interface Command {
  turn: number;
  op: OpName;
  /** actor entity id (move/attack/ability); passenger for load */
  unit?: number;
  /** attack/ability target; carrier for load */
  target?: number;
  /** deploy: slot id; cast: spell id; ability: kind ("heal" | "jam" | "unload" | "hero") */
  id?: string;
  level?: number;
  /** deploy / cast / ability cell */
  to?: Cell;
  /** move: cells after the start cell, 8-neighbour steps */
  path?: Cell[];
}

export interface PlacedBuilding { ID: string; Level: number; Pos: Cell; Revealed: boolean }
export interface GarrisonUnit { ID: string; Level: number }
export interface ArmySlot { ID: string; Level: number; Count: number }

/**
 * Frozen defender base + attacker loadout + content-derived Rules (sim/rules.go; the server builds Rules from
 * content/*.yaml). The client view must not contain hidden traps (OQ-7.8). `Rules` is intentionally loose here:
 * its shape is Go `sim.Rules` and is produced by server/WASM callers, not hand-written in the client.
 */
export interface Snapshot {
  ContentVersion: string;
  BaseID: string;
  Map: string;
  Buildings: PlacedBuilding[] | null;
  Garrison: GarrisonUnit[] | null;
  Army: ArmySlot[] | null;
  Spells: ArmySlot[] | null;
  Hero: string;
  HeroLevel: number;
  Rules: Record<string, unknown>;
}

/** sim.EndReason: 0 none, 1 full_destruction, 2 no_units, 3 turn_limit, 4 retreat, 5 log_end. */
export type EndReason = 0 | 1 | 2 | 3 | 4 | 5;

/** sim.RejectCode: 1 bad_phase, 2 bad_turn, 3 unknown_entity, 4 not_owner, 5 no_ap, 6 cooldown, 7 bad_path,
 *  8 path_cost, 9 out_of_zone, 10 cell_occupied, 11 out_of_range, 12 below_min_range, 13 invalid_target,
 *  14 capacity, 15 no_stock, 16 hero_limit, 17 battle_over. */
export type RejectCode = number;

export interface SlotCount { ID: string; Level: number; Count: number }
export interface StorageHit { Entity: number; ContentID: string; Level: number; DamagePermille: number }
export interface LootBasis { Storages: StorageHit[] | null; PercentDestroyed: number; Stars: number }

export interface Result {
  Stars: number;
  Destruction: number;
  /** bit 0 HQ, bit 1 half, bit 2 full */
  StarFlags: number;
  HQDestroyed: boolean;
  TurnsUsed: number;
  EndReason: EndReason;
  LootBasis: LootBasis;
  UnitsLost: SlotCount[] | null;
  SpellsUsed: SlotCount[] | null;
  HeroDamageTaken: number;
  HeroSurvived: boolean;
  Rejected: { Index: number; Code: RejectCode }[] | null;
  EngineVersion: string;
  /** 16 hex digits (xxhash64 of the final world). A string, unlike the Go uint64. */
  StateHash: string;
}

/** sim.EventKind: 1 moved, 2 attacked, 3 killed, 4 destroyed, 5 trap_triggered, 6 spell_cast, 7 effect_tick,
 *  8 healed, 9 released, 10 turn_ended, 11 battle_ended, 12 spawned (a decoy, SIM-5). Animation only; not part of
 *  StateHash. */
export interface Event { Kind: number; Actor: number; Target: number; Cell: Cell; Value: number }

/** sim.BattlePhase: 0 deploy, 1 player, 2 over. */
export type BattlePhase = 0 | 1 | 2;

/** sim.EntityKind: 0 building, 1 defence, 2 wall, 3 troop, 4 vehicle, 5 ship, 6 hero, 7 decoy. */
export type EntityKind = number;

/** Client view of one entity (sim.EntityState, contract 0.2.5). Entities are never removed: dead ones have Alive=false. */
export interface EntityState {
  ID: number;
  /** 0 defender, 1 attacker */
  Owner: number;
  Kind: EntityKind;
  ContentID: string;
  Level: number;
  /** top-left tile; meaningful when OnField */
  Pos: Cell;
  W: number;
  H: number;
  HP: number;
  MaxHP: number;
  /** action points per turn */
  AP: number;
  APLeft: number;
  /** turns until the hero ability is ready */
  Cooldown: number;
  Alive: boolean;
  /** false: inside a bunker / aboard a carrier */
  OnField: boolean;
  Aboard: number;
  Inside: number;
  Cargo: number[] | null;
  Revealed: boolean;
  /** last turn the effect is active, 0 = none: jam / EMP, a_vanish, decoy lifetime */
  DisabledUntil: number;
  StealthUntil: number;
  DecoyUntil: number;
}

/** sim.ZoneKind: 1 airstrike, 2 medkit, 3 smoke, 4 adrenaline. */
export interface ZoneState { Kind: number; Centre: Cell; R: number; First: number; Last: number; DmgPermille: number; MovePermille: number }

/**
 * World at this moment (Battle.State). Derived data, not part of StateHash. No hidden information: a live,
 * unrevealed hidden trap is absent (its id is skipped), the RNG state is not exposed.
 */
export interface State {
  Phase: BattlePhase;
  Turn: number;
  EndReason: EndReason;
  /** ascending ID */
  Entities: EntityState[];
  Zones: ZoneState[] | null;
  SpellsLeft: ArmySlot[] | null;
  SpellsThisTurn: number;
  StockLeft: ArmySlot[] | null;
  HeroUsed: boolean;
}

export type Reply<T> = { ok: true; result: T } | { ok: false; error: string };

/** Every function returns a JSON string of Reply<T>; JSON.parse it. */
export interface FirelineSim {
  /** sim.EngineVersion of the build */
  readonly engineVersion: string;
  /** sim.Run: full replay. Reply<Result>. seed: decimal string or a safe-integer number. */
  run(snapshot: string, commands: string, seed: string | number): string;
  /** sim.NewBattle. Reply<{ handle: number }> (handles start at 1). */
  newBattle(snapshot: string, seed: string | number): string;
  /** Battle.Apply with a JSON Command. Reply<{ events: Event[] }>; a rejected command is NOT an error:
   *  look at result(handle).Rejected. */
  apply(handle: number, command: string): string;
  /** Battle.Result. Reply<Result> */
  result(handle: number): string;
  /** Battle.State (contract 0.2.5): the client view of the world now. Reply<State>. Optional in the type so that 0.2.4 consumers (mocks) still compile; the real module always has it. Derived data, never changes the battle. */
  state?(handle: number): string;
  /** release a battle. Reply<{ freed: true }> */
  free(handle: number): string;
}

declare global {
  // eslint-disable-next-line no-var
  var fireline_sim: FirelineSim | undefined;
  // eslint-disable-next-line no-var
  var fireline_sim_ready: (() => void) | undefined;
}
